{
  "understanding": {
    "purpose": "A compact order or fulfillment table showing item details, amounts, warehouse locations and tracking identifiers.",
    "reading": "Readers scan across a row to check an item and its fulfillment details, and down columns to compare quantities, prices and totals.",
    "groups": [
      "ID and SKU identify each line item.",
      "Color and Size describe the item variant.",
      "Qty, Price, Tax and Total describe the quantity and monetary amounts.",
      "Warehouse and Tracking describe fulfillment and shipment."
    ],
    "keep_intact": [
      "Tracking identifiers and numeric values",
      "Column headers and individual words",
      "SKU and warehouse codes where space permits"
    ],
    "may_wrap": [
      "SKUs at hyphens",
      "Warehouse locations at hyphens; their wrapping can share row height with wrapped SKUs"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [37, 120, 61, 52, 47, 62, 53, 68, 104, 180],
      "idea": "Favor SKU readability while allowing warehouse locations to wrap."
    },
    {
      "name": "B",
      "widths": [37, 75, 61, 52, 47, 62, 53, 68, 149, 180],
      "idea": "Keep warehouse locations on one line and use a compact SKU column that wraps at hyphens."
    },
    {
      "name": "C",
      "widths": [40, 89, 64, 55, 50, 65, 56, 71, 114, 180],
      "idea": "Share space between SKU and warehouse while giving the short descriptive and financial columns a little breathing room."
    }
  ]
}
